**`interface/index.html`**
```html
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Semana Acadêmica — Grade de atividades</title>
  <link rel="stylesheet" href="css/style.css">
</head>
<body>
  <main class="pagina">
    <h1>Grade de atividades</h1>

    <section class="filtros" aria-label="Filtros da grade">
      <div class="filtro">
        <label for="filtro-usuario">Usuário</label>
        <select id="filtro-usuario"></select>
      </div>
      <div class="filtro">
        <label for="filtro-dia">Dia</label>
        <input type="date" id="filtro-dia">
      </div>
      <div class="filtro">
        <label for="filtro-tipo">Tipo</label>
        <select id="filtro-tipo">
          <option value="">Todos</option>
          <option value="palestra">Palestra</option>
          <option value="minicurso">Minicurso</option>
        </select>
      </div>
    </section>

    <p id="status" class="status" role="status" aria-live="polite"></p>

    <ul id="lista-atividades" class="lista-atividades"></ul>
  </main>

  <script src="js/app.js"></script>
</body>
</html>
```

